// Server code in the app (a server action or a scheduled job): read new mail, triage it through the orchestrator,
// then use the stored triage — the inbox in priority order, the ledger totals and its Excel workbook.
import { ledgerTotals, ledgerWorkbook } from "@/mail/triage/ledger";
import { ledger, syncAndTriage, triagedInbox } from "@/mail/triage/service";

export async function morningReview(): Promise<{ urgent: string[]; totals: string; xlsx: Buffer }> {
  await syncAndTriage();
  const inbox = await triagedInbox({ priority: "urgent" });
  const entries = await ledger();
  const totals = ledgerTotals(entries)
    .map(
      (t) =>
        `${t.currency}: income ${t.income}, expenses ${t.expense}, investments ${t.investment}`,
    )
    .join("; ");
  return { urgent: inbox.map((m) => m.subject), totals, xlsx: await ledgerWorkbook(entries) };
}

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

const server = new McpServer({ name: "app-tools", version: "1.0.0" });
server.registerTool(
  "order_status",
  {
    description: "Status of an order by id",
    inputSchema: { orderId: z.string().regex(/^o-[0-9]+$/) },
  },
  async ({ orderId }) => ({ content: [{ type: "text", text: `${orderId}: shipped` }] }),
);
const [clientSide, serverSide] = InMemoryTransport.createLinkedPair();
await server.connect(serverSide);
const client = new Client({ name: "test", version: "1.0.0" });
await client.connect(clientSide);
const tools = await client.listTools();
console.log(tools.tools.map((t) => t.name)); // → ["order_status"]
const res = await client.callTool({ name: "order_status", arguments: { orderId: "o-42" } });
console.log(res.content); // → [{ type: "text", text: "o-42: shipped" }]
const bad = await client.callTool({ name: "order_status", arguments: { orderId: "../etc" } });
console.log(bad.isError); // → true
await client.close();

// Server code in the app (e.g. src/app/api/support/route.ts): an agent turn with one tool that runs in the app.
import { z } from "zod";
import { defineTool, runAgent, type AgentState } from "@/lib/ai/agent";

const lookupOrder = defineTool({
  name: "lookup_order",
  description: "Status of an order by its number",
  parameters: z.object({ order: z.string().regex(/^A-\d+$/) }),
  execute: async ({ order }) => ({ order, status: "shipped" }),
});

export async function supportTurn(
  caller: { organizationId: string; userId: string },
  input: string,
  state: AgentState | null,
) {
  const r = await runAgent({
    ...caller,
    purpose: "support",
    instructions: "You help customers with their orders.",
    input,
    tools: [lookupOrder],
    state,
  });
  // r.reply → show it; r.state → store it for the next turn; r.pending → show Confirm / Cancel.
  return { reply: r.reply, state: r.state, pending: r.pending };
}

