// A server page or action in the app: the active organization's best matches, each with the why of its score.
import { reasonText } from "@/matching/score";
import { matchesFor, type Actor } from "@/matching/service";

export async function topMatches(actor: Actor, count = 5): Promise<string[]> {
  const matches = await matchesFor(actor);
  return matches
    .slice(0, count)
    .map((m) => `${m.record.title} (score ${m.score}): ${m.reasons.map(reasonText).join(", ")}`);
}

// A server action in the app: role check plus the per-record scopes this member may see.
import { can, requireMember } from "@/server/authz";
import { visibleScopes } from "@/server/record-access";
import { UserFacingError } from "@/security/errors";

export async function editableScopes(): Promise<string[] | "all"> {
  const ctx = await requireMember();
  if (!can(ctx.role, "update")) throw new UserFacingError("Viewers cannot edit notes.");
  return visibleScopes(ctx); // "all" or the ids of the member's companies
}

// Server code in the app: run the reminders that are due now (what the cron route's task does on every call) and list
// them for staff. Each appointment gets one reminder per channel, however often this runs.
import { runDueReminders, staffReminders } from "@/reminders/service";

export async function remindNow() {
  const report = await runDueReminders(new Date());
  const pending = (await staffReminders()).filter((r) => r.status === "scheduled");
  return { ...report, scheduled: pending.length };
}

// A server action in the app (e.g. src/app/dashboard/workflow/actions.ts).
import { requireMember } from "@/server/authz";
import { createItem, transition } from "@/workflow/service";

export async function requestAndApprove(workflow: string, approvedState: string): Promise<string> {
  const ctx = await requireMember();
  const id = await createItem(ctx, {
    workflow,
    title: "Sony FX3 · 14–16 Oct",
    dueAt: new Date("2026-10-16"),
  });
  await transition(ctx, id, approvedState, "Approved for the shoot"); // throws if the role cannot
  return id;
}

// Server code in the app (a scheduled job or a server action): read what arrived since the last run, read-only.
import { InboxConfigError } from "@/mail/inbox/config";
import { syncMailbox } from "@/mail/inbox/store";

export async function readNewMail(): Promise<string> {
  try {
    const r = await syncMailbox();
    if (!r.configured) return "Mailbox not configured (MAIL_IMAP_*).";
    return `${r.stored} new email(s); last UID ${r.lastUid}${r.reset ? " (mailbox read from the start)" : ""}.`;
  } catch (err) {
    if (err instanceof InboxConfigError) return err.message;
    throw err;
  }
}

